id:'silvermere',level:'city',name:'High Silvermere',tag:'City of Raptors · seat of House Crownguard',w:2000,h:1300,ground:'#c9cdb4',
summary:'A highland city in the crags of northern Demacia, built beside Knight’s Rock and a waterfall. The Crownguard Mansion stands at the foot of the rock; the Raptor Aerie crowns its summit. Knight’s Rock, the Aerie, the falls and the mansion are from the lore; the rest of the city is invented for the table.',
dims:['City: 2,000 × 1,300 ft (about 0.4 mile wide). Walls 12 ft thick; towers 30 ft across.','Main street 26 ft wide; lanes 12–14 ft; river 42 ft wide.','A person is a 5-ft token: zoom in to move individuals.'],
labels:[{"t":"THE ROCKY HIGHLANDS","x":420,"y":120,"size":22},{"t":"Knight’s Rock","x":1236,"y":556,"size":13},{"t":"Silvermere Falls","x":1500,"y":392,"size":11,"rot":-72}],
lights:[{"x":1190,"y":631,"r":60},{"x":1190,"y":687,"r":26,"moon":true},{"x":1224,"y":424,"r":70},{"x":800,"y":640,"r":90},{"x":930,"y":562,"r":40},{"x":352,"y":700,"r":50},{"x":930,"y":1076,"r":50},{"x":1040,"y":440,"r":60}],
features:[
 {id:'aerie',nolabel:1,n:"Knight’s Rock & Raptor Aerie",x:1236,y:440,r:118,mx:1236,my:392,c:1,d:"A rocky mount at the edge of a waterfall. Atop it sits the Raptor Aerie — headquarters of the Raptor-Knights and their silverwing mounts. A stone stair winds up from the mansion below.",npc:["Raptor-Knight Sorrel Ward","Aerie captain (invented)","Won’t let outsiders near the nests unless they bring good news."],h:"A clutch of eggs is missing from the highest nest. Only someone who can climb Knight’s Rock could have taken them.",notes:["Rock: roughly 330 × 270 ft at the base; the plateau is about 90 ft across.","Silverwing raptors: Large creatures with a 20-ft wingspan."]},
 {id:'mansion',n:"House Crownguard Mansion",rect:[1090,575,1290,705],mx:1190,my:590,c:1,opens:'crownguard',d:"Seat of House Crownguard, at the foot of Knight’s Rock. Its library holds the “Canticle of the Winged Sisters”, an epic poem about Kayle and Morgana. Open the site map for the floor plan (the layout is invented).",npc:["Lord Remy Crownguard","Head of the house (invented)","Stern and kind; will not abandon family or duty."],h:"The Canticle’s last stanza is missing from the library’s copy. The family wants it found quietly.",notes:["Grounds: 200 × 130 ft, to the same scale as the site map."]},
 {id:'falls',nolabel:1,n:"Silvermere Falls",x:1405,y:395,r:62,mx:1470,my:372,c:1,d:"Water thunders down beside Knight’s Rock into a plunge pool, feeding the river that cuts through the city.",npc:["Ferryman Tamsin","River warden (invented)","Says the falls speak on quiet nights."],h:"A body was found in the plunge pool, wearing a Vanguard tabard no unit has issued in years.",notes:["Drop: about 100 ft. The pool is about 100 × 55 ft; the river below is 40 ft wide."]},
 {id:'shrine',n:"Shrine of the Winged Sisters",x:930,y:562,r:34,my:536,c:0,d:"A small shrine to Kayle and Morgana, with two winged statues. Pilgrims light candles for both.",npc:["Sister Marguerite","Shrine keeper (invented)","Quietly keeps a candle lit for Morgana."],h:"The shrine’s statues have been turned to face each other overnight."},
 {id:'market',n:"Highland Market",x:800,y:640,r:104,mx:800,my:572,c:0,d:"A cobbled market plaza with a fountain, ringed by stalls selling mountain goods, raptor-feather charms and smoked meats.",npc:["Old Hesk","Feather merchant (invented)","Sells “lucky” feathers and genuine gossip."],h:"Counterfeit silverwing feathers have flooded the market. The Aerie wants the source.",notes:["Plaza: about 200 × 124 ft; fountain 26 ft across."]},
 {id:'stables',n:"Raptor Stables & Feeding Ground",x:1040,y:440,r:76,my:410,c:0,d:"A fenced feeding ground and two long stables at the foot of the rock. Young raptors are yellow and blue; adults silver.",npc:["Wren the stablehand","Handler (invented)","Whispers that one raptor speaks to him."],h:"A raptor has been poisoned. The culprit knew exactly which trough to use.",notes:["Paddock: 200 × 100 ft; stables 70 ft long."]},
 {id:'highgate',n:"Highland Gate",x:352,y:700,r:42,my:664,c:0,d:"The road west, down toward the Great City. Twin towers flank the arch.",npc:["Gate-sergeant Bryn","Guard (invented)","Suspicious of anyone not carrying a lantern."],h:"A traveler with a petricite-lined pack asks for a lock-free room."},
 {id:'lowgate',n:"Lowgate",x:930,y:1076,r:42,my:1042,c:0,d:"The southern gate; the road continues over the meadow. The river leaves the city at a water gate to the east.",npc:["Toll-keeper Neve","Guard (invented)","Collects tolls — and counts how many carry swords."],h:"A merchant with no goods insists on paying a very large toll."},
 {id:'bridge',n:"Silvermere Bridge",x:1280,y:724,r:40,my:694,c:0,d:"A broad stone bridge, 84 ft long and 24 ft wide, crossing the river toward the eastern quarter.",npc:["Watch-corporal Jory","Guard (invented)","Bored. Very bored."],h:"Someone has tied silk ribbons to the bridge rails — one for each missing child."},
 {id:'tower',n:"North Watchtower",x:700,y:240,r:34,my:208,c:0,d:"A watchtower on the north wall looking toward the Freljord frontier.",npc:["Watch-captain Elric","Guard (invented)","Reads smoke signals and snowfall."],h:"Beacon fires burn in the north — but not the ones the tower requested."}
],
districts:[
 {id:'heights',n:"Crownguard Heights",x:1195,y:800,style:'noble',d:"Mansions at the foot of Knight’s Rock; the Crownguard Mansion dominates the street."},
 {id:'roost',n:"Raptor Roost",x:975,y:380,style:'military',d:"Stables, roosts and riders’ barracks beneath the Aerie."},
 {id:'terraces',n:"Crag Terraces",x:590,y:410,style:'common',d:"Terraced homes cut into the hillside, linked by stone stairs."},
 {id:'stonecut',n:"Stonecutters’ Quarter",x:455,y:770,style:'slum',d:"Quarry workers’ crowded lanes; resentful of the nobles above."},
 {id:'lowgate',n:"Lowgate Row",x:830,y:980,style:'common',d:"Inns and stables near the southern gate."},
 {id:'east',n:"Waterside",x:1530,y:640,style:'common',d:"Homes across the river, reached by the bridge."}
],
